    private LegacySettingNames() {}

    static String translate(String value) {
        return NAMES.getOrDefault(value, value);
    }

    static JsonElement find(JsonObject settings, String name) {
        if (settings.has(name)) {
            return settings.get(name);
        }
        for (Map.Entry<String, JsonElement> entry : settings.entrySet()) {
            if (translate(entry.getKey()).equals(name)) {
                return entry.getValue();
            }
        }
        return null;
    }
